-- 20260910_11_learning_portal.sql
-- Apply after 20260909_10. Additive: no historical accounting writes.

CREATE TABLE public.learning_templates (
 template_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 program text NOT NULL CHECK(program IN ('basic','advanced','voi')),
 version integer NOT NULL CHECK(version>0), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),
 source text NOT NULL, stages jsonb NOT NULL CHECK(jsonb_typeof(stages)='array' AND jsonb_array_length(stages)>0),
 created_at timestamptz NOT NULL DEFAULT now(), created_by uuid REFERENCES auth.users(id) ON DELETE RESTRICT,
 UNIQUE(program,version)
);
CREATE TABLE public.learning_defaults (
 program text PRIMARY KEY CHECK(program IN ('basic','advanced','voi')),
 template_id uuid NOT NULL REFERENCES public.learning_templates ON DELETE RESTRICT
);
CREATE TABLE public.learning_records (
 record_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 class_id uuid NOT NULL REFERENCES public.classes ON DELETE RESTRICT,
 kind text NOT NULL CHECK(kind IN ('class','student','session')),
 student_id uuid REFERENCES public.students ON DELETE RESTRICT,
 session_id uuid REFERENCES public.sessions ON DELETE RESTRICT,
 draft jsonb NOT NULL CHECK(jsonb_typeof(draft)='object'),
 published jsonb CHECK(jsonb_typeof(published)='object'),
 revision integer NOT NULL DEFAULT 1 CHECK(revision>0),
 updated_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz,
 CHECK((kind='student')=(student_id IS NOT NULL) AND (kind='session')=(session_id IS NOT NULL)),
 UNIQUE NULLS NOT DISTINCT(class_id,kind,student_id,session_id)
);
CREATE TABLE public.learning_history (
 history_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 record_id uuid NOT NULL REFERENCES public.learning_records ON DELETE RESTRICT,
 revision integer NOT NULL, body jsonb NOT NULL, was_published boolean NOT NULL,
 actor_id uuid REFERENCES auth.users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(record_id,revision)
);
CREATE TABLE public.parent_portal_settings (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 contact_label text NOT NULL DEFAULT '', contact_url text NOT NULL DEFAULT '',
 admin_emails text[] NOT NULL DEFAULT '{}', email_enabled boolean NOT NULL DEFAULT false,
 revision integer NOT NULL DEFAULT 1
);
INSERT INTO public.parent_portal_settings(singleton) VALUES(true);
CREATE TABLE public.tutor_public_profiles (
 tutor_id uuid PRIMARY KEY REFERENCES public.tutors ON DELETE RESTRICT,
 introduction text NOT NULL CHECK(length(introduction)<=2000), updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE FUNCTION public.learning_month_queue(p_month text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE d date; result jsonb;
BEGIN
 IF auth.uid() IS NULL AND current_setting('request.jwt.claims',true)::jsonb->>'role' IS DISTINCT FROM 'service_role' THEN
  RAISE EXCEPTION 'Chưa đăng nhập.' USING ERRCODE='42501'; END IF;
 IF p_month IS NULL OR p_month !~ '^20[0-9]{2}-(0[1-9]|1[0-2])$' THEN RAISE EXCEPTION 'Tháng không hợp lệ.' USING ERRCODE='22023'; END IF;
 d:=(p_month||'-01')::date;
 WITH candidates AS (
  SELECT DISTINCT s.class_id,r.student_id FROM public.sessions s
  CROSS JOIN LATERAL csat_internal.session_roster(s.session_id) r
  WHERE s.date>=d AND s.date<(d+interval '1 month')::date
   AND s.date<=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date AND s.status<>'cancelled'
 ), rows AS (
  SELECT c.class_id,c.name AS class_name,t.tutor_id,t.name AS tutor_name,st.student_id,st.name AS student_name,
   sr.review_id,coalesce(sr.review_status,'missing') AS status,
   coalesce(cs.status='active',false) AND c.status='active' AND t.status='active' AND t.is_deleted IS NOT TRUE AND (sr.review_status IS DISTINCT FROM 'draft' OR sr.tutor_id=t.tutor_id) AS actionable
  FROM candidates x JOIN public.classes c USING(class_id) JOIN public.students st USING(student_id)
  LEFT JOIN public.tutors t ON t.tutor_id=csat_internal.tutor_on(c.class_id,(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date)
  LEFT JOIN public.class_students cs ON cs.class_id=c.class_id AND cs.student_id=st.student_id
  LEFT JOIN public.student_reviews sr ON sr.class_id=c.class_id AND sr.student_id=st.student_id AND sr.month_year=p_month
  WHERE st.is_deleted IS NOT TRUE AND (public.is_admin() OR public.is_current_class_tutor(c.class_id)
    OR current_setting('request.jwt.claims',true)::jsonb->>'role'='service_role')
 ) SELECT coalesce(jsonb_agg(to_jsonb(rows) ORDER BY tutor_name,class_name,student_name,student_id),'[]') INTO result FROM rows;
 RETURN result;
END $$;

CREATE FUNCTION public.learning_workspace(p_class_id uuid,p_month text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
BEGIN
 IF auth.uid() IS NULL OR (public.is_admin() IS NOT TRUE AND NOT public.is_current_class_tutor(p_class_id)) THEN
  RAISE EXCEPTION 'Không có quyền đọc lớp.' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object(
 'class',(SELECT jsonb_build_object('class_id',class_id,'name',name,'class_type',class_type) FROM public.classes WHERE class_id=p_class_id),
 'templates',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY program,version DESC),'[]') FROM public.learning_templates t),
 'defaults',(SELECT coalesce(jsonb_agg(to_jsonb(d)),'[]') FROM public.learning_defaults d),
 'records',(SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]') FROM public.learning_records r WHERE class_id=p_class_id),
 'students',(SELECT coalesce(jsonb_agg(jsonb_build_object('student_id',s.student_id,'name',s.name) ORDER BY s.name),'[]') FROM public.students s JOIN public.class_students cs USING(student_id) WHERE cs.class_id=p_class_id AND cs.status='active' AND s.is_deleted IS NOT TRUE),
 'sessions',(SELECT coalesce(jsonb_agg(jsonb_build_object('session_id',session_id,'date',date,'status',status) ORDER BY date,session_id),'[]') FROM public.sessions WHERE class_id=p_class_id),
 'queue',(SELECT coalesce(jsonb_agg(x),'[]') FROM jsonb_array_elements(public.learning_month_queue(p_month)) x WHERE x->>'class_id'=p_class_id::text));
END $$;



CREATE FUNCTION csat_internal.valid_learning_body(b jsonb,k text) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE field text; x jsonb;
BEGIN
 IF b IS NULL OR jsonb_typeof(b)<>'object' OR NOT b ?& ARRAY['goal','focus_tags','next_step','stage_index','title','content','continuation','program','format','template_id']
  OR b-ARRAY['goal','focus_tags','next_step','stage_index','title','content','continuation','program','format','template_id']<>'{}'::jsonb THEN RETURN false; END IF;
 FOREACH field IN ARRAY ARRAY['goal','next_step','title','content','continuation'] LOOP
  IF jsonb_typeof(b->field) IS DISTINCT FROM 'string' OR length(b->>field)>(CASE WHEN field='content' THEN 5000 WHEN field='title' THEN 200 ELSE 2000 END) THEN RETURN false; END IF;
 END LOOP;
 IF jsonb_typeof(b->'focus_tags') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 IF jsonb_array_length(b->'focus_tags')>16 OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(b->'focus_tags'))<>jsonb_array_length(b->'focus_tags') THEN RETURN false; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(b->'focus_tags') LOOP
  IF jsonb_typeof(x)<>'string' OR (x#>>'{}') NOT IN ('k-io','k-types','k-conditions','k-loops','k-arrays','k-frequency','k-sorting','k-functions','k-divisors','k-primes','k-gcd','k-factors','k-modulo','k-strings','k-matrix','k-prefix','k-difference','k-vector','k-stack','k-queue','k-set','k-map','k-greedy','k-two-pointers','k-binary','k-hashing','k-dp-state','k-dp-grid','k-knapsack','k-lis','k-brute','k-recursion','s-reading','s-model','s-select','s-correctness','s-complexity','s-code','s-index','s-types','s-test','s-debug','s-trace','s-explain') THEN RETURN false; END IF;
 END LOOP;
 IF b->>'program' IS NOT NULL AND (jsonb_typeof(b->'program')<>'string' OR b->>'program' NOT IN ('basic','advanced','voi')) THEN RETURN false; END IF;
 IF b->>'format' IS NOT NULL AND (jsonb_typeof(b->'format')<>'string' OR b->>'format' NOT IN ('group','individual')) THEN RETURN false; END IF;
 IF b->>'template_id' IS NOT NULL AND (jsonb_typeof(b->'template_id')<>'string' OR b->>'template_id' !~ '^[a-fA-F0-9-]{36}$') THEN RETURN false; END IF;
 IF b->>'stage_index' IS NOT NULL AND (jsonb_typeof(b->'stage_index')<>'number' OR b->>'stage_index' !~ '^[0-9]+$' OR (b->>'stage_index')::integer>29) THEN RETURN false; END IF;
 IF k<>'class' AND (b->>'program' IS NOT NULL OR b->>'format' IS NOT NULL OR b->>'template_id' IS NOT NULL OR b->>'stage_index' IS NOT NULL) THEN RETURN false; END IF;
 IF k='session' AND (b->>'goal'<>'' OR b->>'next_step'<>'' OR jsonb_array_length(b->'focus_tags')<>0) THEN RETURN false; END IF;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION csat_internal.valid_learning_body(jsonb,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE FUNCTION public.save_learning_record(p_class_id uuid,p_kind text,p_student_id uuid,p_session_id uuid,p_expected_revision integer,p_body jsonb,p_publish boolean) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.learning_records%ROWTYPE; tid uuid; template public.learning_templates%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR (public.is_admin() IS NOT TRUE AND NOT public.is_current_class_tutor(p_class_id)) THEN
  RAISE EXCEPTION 'Không có quyền sửa lớp.' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.classes WHERE class_id=p_class_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy lớp.' USING ERRCODE='P0002'; END IF;
 IF p_kind NOT IN ('class','student','session') OR p_kind IS NULL OR p_publish IS NULL OR p_expected_revision IS NULL
  OR ((p_kind='student')<>(p_student_id IS NOT NULL)) OR ((p_kind='session')<>(p_session_id IS NOT NULL)) THEN
  RAISE EXCEPTION 'Phạm vi không hợp lệ.' USING ERRCODE='22023'; END IF;
 IF p_kind='student' AND NOT EXISTS(SELECT 1 FROM public.class_students WHERE class_id=p_class_id AND student_id=p_student_id AND status='active') THEN
  RAISE EXCEPTION 'Học sinh không đang học trong lớp.' USING ERRCODE='42501'; END IF;
 IF p_kind='session' AND NOT EXISTS(SELECT 1 FROM public.sessions WHERE class_id=p_class_id AND session_id=p_session_id) THEN
  RAISE EXCEPTION 'Buổi không thuộc lớp.' USING ERRCODE='42501'; END IF;
 IF NOT csat_internal.valid_learning_body(p_body,p_kind) OR octet_length(p_body::text)>40000
  OR jsonb_typeof(p_body->'focus_tags') IS DISTINCT FROM 'array' OR jsonb_array_length(p_body->'focus_tags')>16 THEN
  RAISE EXCEPTION 'Nội dung không hợp lệ.' USING ERRCODE='22023'; END IF;
 IF p_kind='class' THEN
  IF p_body->>'program' IS NOT NULL AND p_body->>'program' NOT IN ('basic','advanced','voi') THEN RAISE EXCEPTION 'Chương trình không hợp lệ.' USING ERRCODE='22023'; END IF;
  IF p_publish AND (p_body->>'program' IS NULL OR coalesce(p_body->>'format','') NOT IN ('group','individual')) THEN RAISE EXCEPTION 'Chọn chương trình và hình thức học.' USING ERRCODE='22023'; END IF;
  tid:=(p_body->>'template_id')::uuid;
  IF tid IS NOT NULL THEN
   SELECT * INTO template FROM public.learning_templates WHERE template_id=tid AND program=p_body->>'program';
   IF NOT FOUND THEN RAISE EXCEPTION 'Template không khớp chương trình.' USING ERRCODE='22023'; END IF;
   IF p_body->>'stage_index' IS NOT NULL AND ((p_body->>'stage_index')::integer<0 OR (p_body->>'stage_index')::integer>=jsonb_array_length(template.stages)) THEN RAISE EXCEPTION 'Chặng học không hợp lệ.' USING ERRCODE='22023'; END IF;
  ELSIF p_publish AND p_body->>'program'<>'voi' THEN RAISE EXCEPTION 'Chọn phiên bản giáo án trước khi công bố.' USING ERRCODE='22023'; END IF;
 END IF;
 IF p_kind='session' AND p_publish AND coalesce(trim(p_body->>'title'),'')='' THEN RAISE EXCEPTION 'Cần tên nội dung buổi.' USING ERRCODE='22023'; END IF;
 SELECT * INTO r FROM public.learning_records WHERE class_id=p_class_id AND kind=p_kind AND student_id IS NOT DISTINCT FROM p_student_id AND session_id IS NOT DISTINCT FROM p_session_id FOR UPDATE;
 IF coalesce(r.revision,0)<>p_expected_revision THEN RAISE EXCEPTION 'Nội dung đã thay đổi ở phiên khác. Tải lại trước khi lưu.' USING ERRCODE='40001'; END IF;
 IF r.record_id IS NULL THEN
  INSERT INTO public.learning_records(class_id,kind,student_id,session_id,draft,published,published_at)
  VALUES(p_class_id,p_kind,p_student_id,p_session_id,p_body,CASE WHEN p_publish THEN p_body END,CASE WHEN p_publish THEN now() END) RETURNING * INTO r;
 ELSE
  UPDATE public.learning_records SET draft=p_body,revision=revision+1,updated_at=clock_timestamp(),
   published=CASE WHEN p_publish THEN p_body ELSE published END,published_at=CASE WHEN p_publish THEN now() ELSE published_at END
  WHERE record_id=r.record_id RETURNING * INTO r;
 END IF;
 INSERT INTO public.learning_history(record_id,revision,body,was_published,actor_id) VALUES(r.record_id,r.revision,p_body,p_publish,auth.uid());
 RETURN to_jsonb(r);
END $$;

CREATE FUNCTION public.admin_create_learning_template(p_program text,p_title text,p_source text,p_stages jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.learning_templates%ROWTYPE;
BEGIN
 PERFORM csat_internal.require_admin();
 PERFORM pg_advisory_xact_lock(hashtextextended('learning-template',0));
 INSERT INTO public.learning_templates(program,version,title,source,stages,created_by)
 SELECT p_program,coalesce(max(version),0)+1,p_title,p_source,p_stages,auth.uid() FROM public.learning_templates WHERE program=p_program RETURNING * INTO r;
 RETURN to_jsonb(r);
END $$;
CREATE FUNCTION public.admin_learning_settings(p_action text,p_data jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE t public.learning_templates%ROWTYPE;
BEGIN
 PERFORM csat_internal.require_admin();
 IF p_action='default' THEN
  SELECT * INTO STRICT t FROM public.learning_templates WHERE template_id=(p_data->>'template_id')::uuid;
  INSERT INTO public.learning_defaults(program,template_id) VALUES(t.program,t.template_id) ON CONFLICT(program) DO UPDATE SET template_id=excluded.template_id;
 ELSIF p_action='profile' THEN
  IF length(p_data->>'introduction')>2000 THEN RAISE EXCEPTION 'Giới thiệu quá dài.' USING ERRCODE='22023'; END IF;
  INSERT INTO public.tutor_public_profiles(tutor_id,introduction) VALUES((p_data->>'tutor_id')::uuid,p_data->>'introduction')
   ON CONFLICT(tutor_id) DO UPDATE SET introduction=excluded.introduction,updated_at=now();
 ELSIF p_action='settings' THEN
  IF (p_data->>'contact_url')<>'' AND p_data->>'contact_url' !~ '^https://' THEN RAISE EXCEPTION 'Kênh liên hệ cần HTTPS.' USING ERRCODE='22023'; END IF;
  UPDATE public.parent_portal_settings SET contact_label=p_data->>'contact_label',contact_url=p_data->>'contact_url',
   admin_emails=ARRAY(SELECT jsonb_array_elements_text(p_data->'admin_emails')),email_enabled=(p_data->>'email_enabled')::boolean,revision=revision+1
  WHERE singleton AND revision=(p_data->>'revision')::integer;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cấu hình đã thay đổi. Tải lại.' USING ERRCODE='40001'; END IF;
 ELSE RAISE EXCEPTION 'Thao tác không hợp lệ.' USING ERRCODE='22023'; END IF;
END $$;

-- Parent projection uses the existing opaque session, never client-supplied phone/student alone.
CREATE FUNCTION public.parent_learning_portal(p_token_hash text,p_student_id uuid DEFAULT NULL,p_month text DEFAULT NULL,p_review_page integer DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE base jsonb; sid uuid; d date; result jsonb;
BEGIN
 base:=public.get_parent_lookup(p_token_hash,p_student_id);
 sid:=(base->'student'->>'student_id')::uuid;
 IF sid IS NULL THEN RETURN base; END IF;
 IF p_review_page<0 OR p_review_page>10000 OR p_review_page IS NULL THEN RAISE EXCEPTION 'Trang không hợp lệ.' USING ERRCODE='22023'; END IF;
 IF p_month IS NULL THEN p_month:=to_char(now() AT TIME ZONE 'Asia/Ho_Chi_Minh','YYYY-MM'); END IF;
 IF p_month !~ '^20[0-9]{2}-(0[1-9]|1[0-2])$' THEN RAISE EXCEPTION 'Tháng không hợp lệ.' USING ERRCODE='22023'; END IF;
 d:=(p_month||'-01')::date;
 SELECT jsonb_build_object(
 'month',p_month,
 'plans',coalesce((SELECT jsonb_agg(jsonb_build_object('class_id',r.class_id,'class_name',c.name,'kind',r.kind,'body',r.published,'published_at',r.published_at,
  'template',(SELECT jsonb_build_object('template_id',t.template_id,'version',t.version,'title',t.title,'program',t.program,'source',t.source,'stages',t.stages) FROM public.learning_templates t WHERE t.template_id=(r.published->>'template_id')::uuid)))
  FROM public.learning_records r JOIN public.classes c USING(class_id) WHERE r.published IS NOT NULL AND (r.kind='student' AND r.student_id=sid OR r.kind='class' AND EXISTS(SELECT 1 FROM public.class_students cs WHERE cs.class_id=r.class_id AND cs.student_id=sid AND cs.status='active'))),'[]'::jsonb),
 'attendance',coalesce((SELECT jsonb_agg(jsonb_build_object('session_id',s.session_id,'class_name',c.name,'date',s.date,'start_time',s.start_time,'end_time',s.end_time,'session_status',s.status,'status',a.status,
   'lesson',lr.published) ORDER BY s.date DESC,s.start_time DESC,s.session_id)
  FROM public.sessions s JOIN public.classes c USING(class_id)
  LEFT JOIN csat_internal.effective_attendance a ON a.session_id=s.session_id AND a.student_id=sid
  LEFT JOIN public.learning_records lr ON lr.session_id=s.session_id AND lr.kind='session'
  WHERE s.date>=d AND s.date<(d+interval '1 month')::date AND EXISTS(SELECT 1 FROM csat_internal.session_roster(s.session_id) r WHERE r.student_id=sid)),'[]'::jsonb),
 'invoices',coalesce((SELECT jsonb_agg(jsonb_build_object('payment_id',p.payment_id,'class_name',c.name,'period',p.billing_period,
   'amount',p.amount+coalesce((SELECT sum(a.tuition_delta) FROM public.billing_adjustments a WHERE a.payment_id=p.payment_id),0),
   'balance',csat_internal.payment_balance(p.payment_id)) ORDER BY p.created_at DESC,p.payment_id)
  FROM public.payments p LEFT JOIN public.classes c USING(class_id) WHERE p.student_id=sid),'[]'::jsonb),
 'provisional',coalesce((SELECT jsonb_agg(jsonb_build_object('class_name',x.class_name,'month',x.month,'amount',x.amount,'unknown',x.unknown) ORDER BY x.month DESC,x.class_name) FROM (
  SELECT c.name AS class_name,to_char(s.date,'YYYY-MM') AS month,
   sum(CASE WHEN a.status='attended' THEN a.tuition_fee_snapshot WHEN a.status='absent' THEN 0 END) AS amount,
   count(*) FILTER(WHERE a.status IS NULL OR a.status='attended' AND a.tuition_fee_snapshot IS NULL) AS unknown
  FROM public.sessions s JOIN public.classes c USING(class_id)
  LEFT JOIN csat_internal.effective_attendance a ON a.session_id=s.session_id AND a.student_id=sid
  WHERE s.billing_period IS NULL AND s.status<>'cancelled' AND (s.date+s.end_time) <= (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')
   AND EXISTS(SELECT 1 FROM csat_internal.session_roster(s.session_id) r WHERE r.student_id=sid)
  GROUP BY c.class_id,c.name,to_char(s.date,'YYYY-MM')) x),'[]'::jsonb),
 'tutors',coalesce((SELECT jsonb_agg(jsonb_build_object('class_name',c.name,'name',t.name,'introduction',p.introduction))
  FROM public.class_students cs JOIN public.classes c USING(class_id)
  LEFT JOIN public.tutors t ON t.tutor_id=csat_internal.tutor_on(c.class_id,(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date)
  LEFT JOIN public.tutor_public_profiles p ON p.tutor_id=t.tutor_id WHERE cs.student_id=sid AND cs.status='active'),'[]'::jsonb),
 'contact',(SELECT jsonb_build_object('label',contact_label,'url',contact_url) FROM public.parent_portal_settings WHERE singleton),
 'reviewPage',p_review_page,
 'reviewCount',(SELECT count(*) FROM public.student_reviews WHERE student_id=sid AND review_status='published'),
 'reviews',coalesce((SELECT jsonb_agg(x.doc ORDER BY x.month_year DESC,x.review_id) FROM (
  SELECT r.month_year,r.review_id,jsonb_build_object('review_id',r.review_id,'month_year',r.month_year,'review_context',r.review_context,
   'general_assessment',r.general_assessment,'learning_attitude',r.learning_attitude,'logical_thinking',r.logical_thinking,'review_tags',r.review_tags,
   'classes',jsonb_build_object('name',c.name),'tutors',jsonb_build_object('name',t.name)) AS doc
  FROM public.student_reviews r LEFT JOIN public.classes c USING(class_id) LEFT JOIN public.tutors t ON t.tutor_id=r.tutor_id
  WHERE r.student_id=sid AND r.review_status='published' ORDER BY r.month_year DESC,r.review_id LIMIT 12 OFFSET p_review_page*12) x),'[]'::jsonb)
 ) INTO result;
 RETURN base||result;
END $$;

DO $$ DECLARE t text; f record; BEGIN
 FOREACH t IN ARRAY ARRAY['learning_templates','learning_defaults','learning_records','learning_history','parent_portal_settings','tutor_public_profiles'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);
  EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);
  EXECUTE format('CREATE POLICY admin_read ON public.%I FOR SELECT TO authenticated USING(public.is_admin())',t);
 END LOOP;
 FOR f IN SELECT oid::regprocedure AS sig FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('learning_month_queue','learning_workspace','save_learning_record','admin_create_learning_template','admin_learning_settings','parent_learning_portal') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,service_role',f.sig);
  IF f.sig::text NOT LIKE '%parent_learning_portal%' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',f.sig); END IF;
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION public.parent_learning_portal(text,uuid,text,integer),public.learning_month_queue(text) TO service_role;
CREATE TRIGGER immutable_template BEFORE UPDATE OR DELETE ON public.learning_templates FOR EACH ROW EXECUTE FUNCTION csat_internal.immutable_record();
CREATE TRIGGER immutable_learning_history BEFORE UPDATE OR DELETE ON public.learning_history FOR EACH ROW EXECUTE FUNCTION csat_internal.immutable_record();
INSERT INTO csat_internal.schema_migrations(version) VALUES('20260910_11');



-- 20260910_12_learning_templates.sql
-- Initial approved reference templates; no class/student progress is inferred.

INSERT INTO public.learning_templates(template_id,program,version,title,source,stages) VALUES('30000000-0000-4000-8000-000000000001','basic',1,'CSAT · Cơ bản · 30 buổi','Kiến thức dự kiến C++.pdf, trang 1 (thứ tự và nhóm buổi); Danh sách kiến thức.xlsx (tham chiếu chuyên môn). Diễn giải giáo dục từ bản mẫu đã duyệt; các phần ghi “đề xuất” cần gia sư xác nhận phạm vi trước khi dạy.','[{"title":"C++ & điều kiện","range":"1–8","description":"Con làm quen với cách chuyển yêu cầu của bài toán thành một chương trình, từ phép tính đơn giản đến việc xử lý nhiều trường hợp.","outcomes":["Phân biệt dữ liệu đầu vào và kết quả cần tìm.","Viết và kiểm tra chương trình có điều kiện."],"lessons":[{"range":"1","title":"Xuất dữ liệu","description":"Chạy chương trình, xuất kết quả đúng định dạng.","source":"Kiến thức dự kiến C++.pdf · A01–A03"},{"range":"2","title":"Các loại biến, nhập biến, gán biến","description":"Phân biệt dữ liệu vào, kiểu dữ liệu và phép gán.","source":"Kiến thức dự kiến C++.pdf · A01–A03"},{"range":"3","title":"Tính toán","description":"Biểu thức, chia nguyên, chia lấy dư, ép kiểu và tràn số.","source":"Kiến thức dự kiến C++.pdf · A01–A03"},{"range":"4","title":"Ôn tập 1","description":"Kết hợp nhập–xuất và tính toán.","source":"Kiến thức dự kiến C++.pdf · A01–A03"},{"range":"5–6","title":"Cấu trúc điều kiện","description":"So sánh, logic, phân chia trường hợp và kiểm tra giá trị biên.","source":"Kiến thức dự kiến C++.pdf · A01–A03"},{"range":"7–8","title":"Ôn tập 2, 3","description":"Luyện bài nhiều điều kiện, kiểm tra trường hợp bị bỏ sót.","source":"Kiến thức dự kiến C++.pdf · A01–A03"}]},{"title":"Vòng lặp & duyệt","range":"9–13","description":"Con học cách tổ chức công việc lặp lại, thử các phương án và tìm điều kiện để chương trình kết thúc đúng.","outcomes":["Dùng vòng lặp để tính tổng, đếm và mô phỏng.","Theo dõi biến và kiểm tra điều kiện dừng."],"lessons":[{"range":"9","title":"Cấu trúc lặp — For","description":"Duyệt một khoảng, tính tổng và đếm.","source":"Kiến thức dự kiến C++.pdf · A04 · liên hệ B01"},{"range":"10","title":"Cấu trúc lặp — While","description":"Lặp theo điều kiện và xác định điểm dừng.","source":"Kiến thức dự kiến C++.pdf · A04 · liên hệ B01"},{"range":"11","title":"Cấu trúc lặp lồng nhau","description":"Duyệt cặp, mô phỏng và thử phương án.","source":"Kiến thức dự kiến C++.pdf · A04 · liên hệ B01"},{"range":"12–13","title":"Ôn tập 4, 5","description":"Kết hợp điều kiện và vòng lặp.","source":"Kiến thức dự kiến C++.pdf · A04 · liên hệ B01"}]},{"title":"Dãy & mảng","range":"14–18","description":"Con học cách lưu và xử lý một dãy số: tìm giá trị cần thiết, đếm số lần xuất hiện và nhận ra vai trò của thứ tự các phần tử.","outcomes":["Phân biệt vị trí, giá trị và đoạn liên tiếp.","Chọn cách duyệt, đếm hoặc sắp xếp phù hợp.","Tự kiểm tra bài với phần tử trùng nhau và dữ liệu biên."],"lessons":[{"range":"14","title":"Mảng một chiều","description":"Lưu dãy, duyệt, tìm cực trị và tính tổng.","source":"Kiến thức dự kiến C++.pdf · A05–A06 · B12"},{"range":"15","title":"Kỹ thuật đánh dấu, truy vấn mảng","description":"Đánh dấu xuất hiện, đếm tần suất, truy vấn đơn giản.","source":"Kiến thức dự kiến C++.pdf · A05–A06 · B12"},{"range":"16","title":"Sắp xếp mảng","description":"Thứ tự tăng/giảm và cách sử dụng sắp xếp.","source":"Kiến thức dự kiến C++.pdf · A05–A06 · B12"},{"range":"17–18","title":"Ôn tập 5, 6","description":"Đề xuất làm rõ bài toán dãy, đoạn liên tiếp và thao tác mảng.","source":"Kiến thức dự kiến C++.pdf · A05–A06 · B12"}]},{"title":"Số học & hàm","range":"19–24","description":"Từ tính chất của số nguyên, con xây dựng cách kiểm tra và tính toán; sau đó tổ chức các thao tác thành hàm có nhiệm vụ rõ ràng.","outcomes":["Áp dụng tính chia hết, nguyên tố và ƯCLN/BCNN.","Giải thích khi nào dùng kiểm tra từng số hoặc sàng."],"lessons":[{"range":"19–21","title":"Số học","description":"Đề xuất: chia hết, ước/bội, số chính phương, nguyên tố, ƯCLN/BCNN.","source":"Kiến thức dự kiến C++.pdf · A08 · B02–B05"},{"range":"22","title":"Hàm trả về giá trị","description":"Tham số, kết quả trả về và phạm vi biến.","source":"Kiến thức dự kiến C++.pdf · A08 · B02–B05"},{"range":"23","title":"Hàm void — Sàng","description":"Hàm không trả về giá trị và sàng Eratosthenes.","source":"Kiến thức dự kiến C++.pdf · A08 · B02–B05"},{"range":"24","title":"Ôn tập 7","description":"Kết hợp số học, hàm và sàng.","source":"Kiến thức dự kiến C++.pdf · A08 · B02–B05"}]},{"title":"Xâu & ma trận","range":"25–29","description":"Con mở rộng cách biểu diễn dữ liệu từ dãy số sang văn bản và bảng, luyện xử lý ký tự, hàng, cột và chỉ số.","outcomes":["Xử lý xâu, khoảng trắng và đếm ký tự.","Duyệt dữ liệu hai chiều đúng phạm vi."],"lessons":[{"range":"25–26","title":"Xâu ký tự","description":"Duyệt, nhập cả dòng, thao tác cơ bản với string.","source":"Kiến thức dự kiến C++.pdf · A07 · A09 · B14"},{"range":"27","title":"Xử lý xâu","description":"Đếm ký tự, tách từ, chuẩn hóa và đối xứng.","source":"Kiến thức dự kiến C++.pdf · A07 · A09 · B14"},{"range":"28","title":"Mảng hai chiều","description":"Hàng, cột, đường chéo và dữ liệu dạng bảng.","source":"Kiến thức dự kiến C++.pdf · A07 · A09 · B14"},{"range":"29","title":"Ôn tập 8","description":"Tổng hợp kiến thức và củng cố lỗi còn lặp lại.","source":"Kiến thức dự kiến C++.pdf · A07 · A09 · B14"}]},{"title":"Đánh giá tổng kết","range":"30","description":"Buổi tổng kết giúp xác định phần con đã vận dụng được, nội dung cần củng cố và chặng học tiếp phù hợp.","outcomes":["Tự giải thích ý tưởng, cài đặt và kiểm tra bài.","Nhận được định hướng dựa trên minh chứng thực tế."],"lessons":[{"range":"30","title":"Kiểm tra tổng kết","description":"Đánh giá khả năng tự giải, cài đặt, giải thích và kiểm thử.","source":"Kiến thức dự kiến C++.pdf · Tổng hợp nội dung đã học"}]}]'::jsonb);
INSERT INTO public.learning_defaults(program,template_id) VALUES('basic','30000000-0000-4000-8000-000000000001');
INSERT INTO public.learning_templates(template_id,program,version,title,source,stages) VALUES('30000000-0000-4000-8000-000000000002','advanced',1,'CSAT · Nâng cao · 35 buổi','Kiến thức dự kiến C++.pdf, trang 2 (thứ tự và nhóm buổi); Danh sách kiến thức.xlsx (tham chiếu chuyên môn). Diễn giải giáo dục từ bản mẫu đã duyệt; các phần ghi “đề xuất” cần gia sư xác nhận phạm vi trước khi dạy.','[{"title":"Số học, dãy & xâu","range":"1–12","description":"Con củng cố nền tảng và học cách tiền xử lý thông tin để giải các bài toán trên dãy, bảng và xâu hiệu quả hơn.","outcomes":["Phân biệt truy vấn dữ liệu và cập nhật dữ liệu.","Kết hợp tính chất số học với cách tổ chức dữ liệu."],"lessons":[{"range":"1–2","title":"Số học cơ bản","description":"Rà soát nền tảng; nối tiếp phân tích thừa số nguyên tố.","source":"Kiến thức dự kiến C++.pdf · B06–B08 · B14 · C01–C02"},{"range":"3–4","title":"Mảng tổng","description":"Mảng cộng dồn, tổng đoạn và tiền xử lý.","source":"Kiến thức dự kiến C++.pdf · B06–B08 · B14 · C01–C02"},{"range":"5–6","title":"Dãy","description":"Phần tử, đoạn liên tiếp, đếm và cực trị trên dãy.","source":"Kiến thức dự kiến C++.pdf · B06–B08 · B14 · C01–C02"},{"range":"7","title":"Mảng hiệu","description":"Biểu diễn thay đổi, cập nhật đoạn và khôi phục dữ liệu.","source":"Kiến thức dự kiến C++.pdf · B06–B08 · B14 · C01–C02"},{"range":"8","title":"Ma trận","description":"Đề xuất nối tiếp cộng dồn hai chiều và truy vấn hình chữ nhật.","source":"Kiến thức dự kiến C++.pdf · B06–B08 · B14 · C01–C02"},{"range":"9","title":"Số học nâng cao","description":"Đề xuất trọng tâm modulo và lũy thừa nhanh.","source":"Kiến thức dự kiến C++.pdf · B06–B08 · B14 · C01–C02"},{"range":"10–11","title":"Xâu","description":"Bài tổng hợp đếm, đối xứng và xử lý đoạn xâu.","source":"Kiến thức dự kiến C++.pdf · B06–B08 · B14 · C01–C02"},{"range":"12","title":"Ôn tập 1","description":"Tổng hợp số học, dãy, ma trận và xâu.","source":"Kiến thức dự kiến C++.pdf · B06–B08 · B14 · C01–C02"}]},{"title":"Cấu trúc dữ liệu","range":"13–19","description":"Con tìm hiểu các cách lưu và truy xuất thông tin, từ đó chọn công cụ theo yêu cầu thực sự của bài toán.","outcomes":["Giải thích lựa chọn cấu trúc dữ liệu.","Phối hợp cấu trúc dữ liệu với sắp xếp."],"lessons":[{"range":"13","title":"Stack","description":"Ngăn xếp và nguyên tắc vào sau–ra trước.","source":"Kiến thức dự kiến C++.pdf · B09–B12 · C04–C06"},{"range":"14","title":"Queue & Deque","description":"Hàng đợi và hàng đợi hai đầu.","source":"Kiến thức dự kiến C++.pdf · B09–B12 · C04–C06"},{"range":"15","title":"Set & Multiset","description":"Dữ liệu có thứ tự; phân biệt phần tử duy nhất và phần tử lặp.","source":"Kiến thức dự kiến C++.pdf · B09–B12 · C04–C06"},{"range":"16","title":"Map","description":"Ánh xạ khóa–giá trị, đếm và gom thông tin.","source":"Kiến thức dự kiến C++.pdf · B09–B12 · C04–C06"},{"range":"17","title":"Vector","description":"Mảng động, kích thước và các thao tác.","source":"Kiến thức dự kiến C++.pdf · B09–B12 · C04–C06"},{"range":"18","title":"Sắp xếp","description":"Sắp theo tiêu chí; đề xuất bổ trợ pair/struct.","source":"Kiến thức dự kiến C++.pdf · B09–B12 · C04–C06"},{"range":"19","title":"Ôn tập 2","description":"Chọn cấu trúc dữ liệu và phối hợp với sắp xếp.","source":"Kiến thức dự kiến C++.pdf · B09–B12 · C04–C06"}]},{"title":"Tham lam & hai con trỏ","range":"20–23","description":"Con học cách giảm công việc phải thực hiện, đồng thời giải thích vì sao chiến lược lựa chọn hoặc di chuyển không bỏ sót đáp án.","outcomes":["Kiểm tra điều kiện áp dụng và tìm phản ví dụ.","Giải thích quy luật di chuyển của hai con trỏ."],"lessons":[{"range":"20–21","title":"Tham lam","description":"Lựa chọn cục bộ, điều kiện áp dụng và lập luận tính đúng.","source":"Kiến thức dự kiến C++.pdf · C03 · C10"},{"range":"22–23","title":"Hai con trỏ","description":"Quy luật di chuyển và cửa sổ trượt khi phù hợp.","source":"Kiến thức dự kiến C++.pdf · C03 · C10"}]},{"title":"Nhị phân & băm","range":"24–27","description":"Con tìm đáp án bằng cách thu hẹp miền tìm kiếm có cơ sở. Phần Hashing cần thống nhất phạm vi chuyên môn trước khi giảng dạy.","outcomes":["Xác định tính đơn điệu và xử lý biên khi tìm kiếm.","Hiểu khái niệm băm và khả năng va chạm nếu học băm xâu."],"lessons":[{"range":"24–26","title":"Tìm kiếm nhị phân","description":"Trên dãy sắp xếp và trên đáp án với hàm kiểm tra đơn điệu.","source":"Kiến thức dự kiến C++.pdf · B13 · C11 · Hashing trong PDF"},{"range":"27","title":"Hashing","description":"PDF chưa xác định loại băm. Đề xuất băm xâu nhập môn, kèm khái niệm va chạm.","source":"Kiến thức dự kiến C++.pdf · B13 · C11 · Hashing trong PDF"}]},{"title":"Quy hoạch động","range":"28–31","description":"Con học cách liên kết kết quả của những bài toán nhỏ để giải bài toán lớn, xác định điều cần lưu và thứ tự tính phù hợp.","outcomes":["Tự mô tả trạng thái và điều kiện đầu.","Giải thích công thức chuyển và thứ tự tính.","Phân biệt giá trị đáp án với cách dựng lại lời giải."],"lessons":[{"range":"28–31","title":"Quy hoạch động","description":"Đề xuất: trạng thái một chiều, trên lưới, cái túi 0/1, LIS và truy vết cơ bản.","source":"Kiến thức dự kiến C++.pdf · Trọng tâm đề xuất D01–D05"}]},{"title":"Vét cạn & tổng hợp","range":"32–35","description":"Con hệ thống hóa cách thử phương án, bổ sung đệ quy–quay lui và nhìn lại cách phối hợp kiến thức qua bài tổng hợp.","outcomes":["Nhận biết giới hạn khả thi của vét cạn.","Giải thích điều kiện dừng và chọn–thử–hoàn tác."],"lessons":[{"range":"32","title":"Brute force","description":"Hệ thống hóa vét cạn, giới hạn khả thi và kiểm chứng lời giải.","source":"Kiến thức dự kiến C++.pdf · B01 · B07 · C07–C08; C09 cần bố trí riêng"},{"range":"33","title":"Số học áp dụng","description":"Phối hợp tính chất số học; đề xuất Legendre trong bài về giai thừa.","source":"Kiến thức dự kiến C++.pdf · B01 · B07 · C07–C08; C09 cần bố trí riêng"},{"range":"34","title":"Đệ quy — Quay lui","description":"Điều kiện dừng, chọn–thử–hoàn tác và sinh cấu hình.","source":"Kiến thức dự kiến C++.pdf · B01 · B07 · C07–C08; C09 cần bố trí riêng"},{"range":"35","title":"Ôn tập 3","description":"Giải bài tổng hợp, sửa bài và định hướng học tiếp.","source":"Kiến thức dự kiến C++.pdf · B01 · B07 · C07–C08; C09 cần bố trí riêng"}]}]'::jsonb);
INSERT INTO public.learning_defaults(program,template_id) VALUES('advanced','30000000-0000-4000-8000-000000000002');
INSERT INTO csat_internal.schema_migrations(version) VALUES('20260910_12');



-- 20260910_13_monthly_workflows.sql

CREATE POLICY tutor_read_class_reviews ON public.student_reviews FOR SELECT TO authenticated
 USING(public.is_current_class_tutor(class_id));
CREATE TABLE public.review_email_runs (
 month text PRIMARY KEY CHECK(month ~ '^20[0-9]{2}-(0[1-9]|1[0-2])$'),
 snapshot jsonb NOT NULL, sender text NOT NULL, origin text NOT NULL, admin_emails text[] NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.review_email_outbox (
 outbox_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), month text NOT NULL REFERENCES public.review_email_runs ON DELETE RESTRICT,
 kind text NOT NULL CHECK(kind IN ('tutor','admin')), recipient_key text NOT NULL, recipient text NOT NULL,
 payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sending','accepted','failed','manual_review','skipped')),
 attempts integer NOT NULL DEFAULT 0, first_attempt_at timestamptz, lease_until timestamptz, lease_id uuid,
 next_attempt_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, provider_id text, error_code text,
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(month,kind,recipient_key)
);
CREATE INDEX review_email_pending_idx ON public.review_email_outbox(next_attempt_at) WHERE status IN ('queued','failed','sending');
ALTER TABLE public.review_email_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.review_email_outbox ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.review_email_runs,public.review_email_outbox FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public.review_email_runs,public.review_email_outbox TO authenticated;
CREATE POLICY admin_read ON public.review_email_runs FOR SELECT TO authenticated USING(public.is_admin());
CREATE POLICY admin_read ON public.review_email_outbox FOR SELECT TO authenticated USING(public.is_admin());

CREATE FUNCTION public.review_email_work(p_action text,p_data jsonb DEFAULT '{}') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE local_now timestamp:=now() AT TIME ZONE 'Asia/Ho_Chi_Minh'; m text; q jsonb; tutor_record record; r public.review_email_runs%ROWTYPE;
 settings public.parent_portal_settings%ROWTYPE; o public.review_email_outbox%ROWTYPE; content text; addr text; result jsonb;
BEGIN
 IF auth.jwt()->>'role' IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Chỉ máy chủ gửi email.' USING ERRCODE='42501'; END IF;
 SELECT * INTO settings FROM public.parent_portal_settings WHERE singleton;
 IF NOT settings.email_enabled THEN RETURN jsonb_build_object('disabled',true); END IF;
 IF p_action='status' THEN RETURN jsonb_build_object('disabled',false); END IF;
 IF p_action='prepare' THEN
  IF extract(day FROM local_now)<>28 OR local_now::time<'08:00'::time THEN RETURN jsonb_build_object('outside_schedule',true); END IF;
  IF coalesce(p_data->>'origin','') !~ '^https://[^/]+$' OR coalesce(p_data->>'sender','')='' THEN RAISE EXCEPTION 'Thiếu cấu hình email.' USING ERRCODE='22023'; END IF;
  m:=to_char(local_now,'YYYY-MM');
  PERFORM pg_advisory_xact_lock(hashtextextended('review-email-'||m,0));
  IF EXISTS(SELECT 1 FROM public.review_email_runs WHERE month=m) THEN RETURN jsonb_build_object('existing',true); END IF;
  q:=public.learning_month_queue(m);
  INSERT INTO public.review_email_runs(month,snapshot,sender,origin,admin_emails)
   VALUES(m,q,p_data->>'sender',p_data->>'origin',settings.admin_emails) RETURNING * INTO r;
  FOR tutor_record IN SELECT tu.tutor_id,tu.name,tu.email,jsonb_agg(x) AS students
   FROM jsonb_array_elements(q) x JOIN public.tutors tu ON tu.tutor_id=(x->>'tutor_id')::uuid
   WHERE x->>'status'<>'published' AND (x->>'actionable')::boolean
   GROUP BY tu.tutor_id,tu.name,tu.email LOOP
   content:='Chào '||tutor_record.name||E',\n\nVui lòng hoàn thiện nhận xét tháng '||m||E' cho các học sinh sau:\n'||
    (SELECT string_agg('- '||(x->>'student_name')||' · '||(x->>'class_name')||' · '||
     CASE WHEN x->>'status'='draft' THEN 'Bản nháp' ELSE 'Chưa viết' END||E'\n'||
     r.origin||'/tutor/classes/'||(x->>'class_id')||'/students/'||(x->>'student_id')||'/review?month='||m,E'\n\n' ORDER BY x->>'class_name',x->>'student_name')
     FROM jsonb_array_elements(tutor_record.students) x)||
    E'\n\nĐăng nhập tài khoản gia sư để mở biểu mẫu. Nhận xét chỉ xuất hiện với phụ huynh sau khi bạn chọn Gửi nhận xétutor_record. Chốt sổ do admin thực hiện riêng.';
   addr:=lower(trim(coalesce(tutor_record.email,'')));
   INSERT INTO public.review_email_outbox(month,kind,recipient_key,recipient,payload,status,error_code)
    VALUES(m,'tutor',tutor_record.tutor_id::text,addr,
     jsonb_build_object('from',r.sender,'to',jsonb_build_array(addr),'subject','CSAT · Nhắc nhận xét tháng '||m,'text',content),
     CASE WHEN addr ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN 'queued' ELSE 'skipped' END,
     CASE WHEN addr !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN 'missing_email' END);
  END LOOP;
  RETURN jsonb_build_object('prepared',true,'month',m);
 ELSIF p_action='admin' THEN
  FOR r IN SELECT * FROM public.review_email_runs WHERE month=to_char(local_now,'YYYY-MM') LOOP
   -- Wait until every tutor has at least been attempted; include known failures in the one admin digest.
   IF EXISTS(SELECT 1 FROM public.review_email_outbox WHERE month=r.month AND kind='tutor' AND status IN ('queued','sending')) THEN CONTINUE; END IF;
   content:='Tổng hợp nhận xét tháng '||r.month||E' tại thời điểm nhắc ngày 28.\n\n'||
    coalesce((SELECT string_agg(y.line,E'\n') FROM (
     SELECT coalesce(x->>'tutor_name','Chưa phân gia sư')||' · '||(x->>'class_name')||
      ': đã gửi '||count(*) FILTER(WHERE x->>'status'='published')||', nháp '||count(*) FILTER(WHERE x->>'status'='draft')||
      ', chưa viết '||count(*) FILTER(WHERE x->>'status'='missing')||
      ', cần kiểm tra phân công '||count(*) FILTER(WHERE NOT (x->>'actionable')::boolean) AS line
     FROM jsonb_array_elements(r.snapshot) x GROUP BY x->>'tutor_name',x->>'class_name' ORDER BY x->>'tutor_name',x->>'class_name') y),'Chưa có học sinh cần tổng hợp.')||
    E'\n\nLượt gửi nhắc gia sư:\n'||coalesce((SELECT string_agg(coalesce(tutor_row.name,email_row.recipient_key)||': '||email_row.status||coalesce(' · '||email_row.error_code,''),E'\n' ORDER BY tutor_row.name)
      FROM public.review_email_outbox email_row LEFT JOIN public.tutors tutor_row ON tutor_row.tutor_id::text=email_row.recipient_key WHERE email_row.month=r.month AND email_row.kind='tutor'),'Không có gia sư cần nhắc.')||
    E'\n\nXem tình hình hiện tại và nhật ký gửi: '||r.origin||E'/admin/learning\n\nAdmin đối chiếu và chốt sổ thủ công. Nhận xét còn thiếu không tự chặn chốt sổ học phí.';
   FOREACH addr IN ARRAY r.admin_emails LOOP
    INSERT INTO public.review_email_outbox(month,kind,recipient_key,recipient,payload)
     VALUES(r.month,'admin',lower(addr),lower(addr),jsonb_build_object('from',r.sender,'to',jsonb_build_array(lower(addr)),'subject','CSAT · Tổng hợp nhận xét tháng '||r.month,'text',content))
     ON CONFLICT(month,kind,recipient_key) DO NOTHING;
   END LOOP;
  END LOOP;
  RETURN jsonb_build_object('ok',true);
 ELSIF p_action='claim' THEN
  -- Provider idempotency expires at 24h. Never blindly retry an uncertain attempt beyond 23h.
  UPDATE public.review_email_outbox SET status='manual_review',error_code='idempotency_window_expired'
   WHERE status IN ('failed','sending') AND first_attempt_at<now()-interval '23 hours';
  UPDATE public.review_email_outbox SET status='manual_review',error_code='attempts_exhausted'
   WHERE status='sending' AND attempts>=3 AND lease_until<now();
  SELECT * INTO o FROM public.review_email_outbox
   WHERE ((status IN ('queued','failed') AND next_attempt_at<=now() AND attempts<3)
      OR (status='sending' AND lease_until<now() AND attempts<3))
    AND (first_attempt_at IS NULL OR first_attempt_at>=now()-interval '23 hours')
   ORDER BY CASE WHEN kind='tutor' THEN 0 ELSE 1 END,created_at,outbox_id FOR UPDATE SKIP LOCKED LIMIT 1;
  IF o.outbox_id IS NULL THEN RETURN NULL; END IF;
  UPDATE public.review_email_outbox SET status='sending',attempts=attempts+1,first_attempt_at=coalesce(first_attempt_at,now()),lease_id=gen_random_uuid(),lease_until=now()+interval '3 minutes'
   WHERE outbox_id=o.outbox_id RETURNING * INTO o;
  RETURN to_jsonb(o);
 ELSIF p_action='finish' THEN
  IF p_data->>'status' NOT IN ('accepted','failed') THEN RAISE EXCEPTION 'Trạng thái không hợp lệ.' USING ERRCODE='22023'; END IF;
  UPDATE public.review_email_outbox SET status=p_data->>'status',provider_id=p_data->>'provider_id',
   error_code=left(p_data->>'error_code',100),accepted_at=CASE WHEN p_data->>'status'='accepted' THEN now() END,
   lease_until=NULL,next_attempt_at=now()+interval '5 minutes'
   WHERE outbox_id=(p_data->>'outbox_id')::uuid AND lease_id=(p_data->>'lease_id')::uuid AND status='sending';
  RETURN jsonb_build_object('updated',FOUND);
 ELSE RAISE EXCEPTION 'Thao tác không hợp lệ.' USING ERRCODE='22023'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.review_email_work(text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.review_email_work(text,jsonb) TO service_role;

CREATE FUNCTION public.create_class_with_learning(p_data jsonb,p_request_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb; cid uuid; prog text; tid uuid; b jsonb;
BEGIN
 PERFORM csat_internal.require_admin();
 result:=public.manage_class('create',NULL,p_data,p_request_id);cid:=(result->>'class_id')::uuid;
 -- Same request retry returns the original class and never rewrites its roadmap.
 IF NOT EXISTS(SELECT 1 FROM public.learning_records WHERE class_id=cid AND kind='class') THEN
  prog:=coalesce(p_data->>'program',CASE WHEN p_data->>'class_type' IN ('Lớp Cơ bản','Cơ bản') THEN 'basic' WHEN p_data->>'class_type' IN ('Lớp Nâng cao','Nâng cao') THEN 'advanced' END);
  SELECT template_id INTO tid FROM public.learning_defaults WHERE program=prog;
  b:=jsonb_build_object('goal','','focus_tags','[]'::jsonb,'next_step','','stage_index',NULL,'title','','content','','continuation','','program',prog,
    'format',coalesce(p_data->>'teaching_format','group'),'template_id',tid);
  PERFORM public.save_learning_record(cid,'class',NULL,NULL,0,b,false);
 END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.create_class_with_learning(jsonb,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.create_class_with_learning(jsonb,uuid) TO authenticated;
